<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElButton, ElAlert, ElDialog } from 'element-plus'
import { callAdmin } from './api'
type OrderItem = { name: string; qty: number; color: string; size: string; pattern: string }
type Order = { _id: string; status: string; version: number; payAmount: number; balancePaid: number; wxPaid: number; refundedAmount?: number; createdAt: string; expressCompany: string; expressNo: string; refundReason: string; address: { name: string; phone: string; region: string; detail: string }; memberNo?: string; items: OrderItem[] }
type Refund = { _id: string; orderId: string; lines: { name: string; color: string; size: string; pattern: string; qty: number; amount: number }[]; reasonCode: string; reasonText: string; goodsAmount: number; freightAmount: number; freightComp: number; totalAmount: number; balanceAmount: number; originalAmount: number; mode: string; status: string; rejectReason: string; createdAt: string }
const orders = ref<Order[]>([]), selected = ref<Order>(), refund = ref<{ balanceAmount: number; originalAmount: number; originalStatus: string }>(), status = ref(''), busy = ref(false), error = ref(''), notice = ref(''), operation = ref(''), company = ref(''), tracking = ref(''), reason = ref('')
const pendingRefunds = ref<Refund[]>([]), orderRefunds = ref<Refund[]>([]), refundRejectId = ref(''), refundRejectReason = ref('')
const mode = ref('original')
const routePick = ref<Record<string, string>>({})
const routeOf = (id: string) => routePick.value[id] || 'source'
const labels: Record<string, string> = { pending_pay: '待付款', pending_ship: '待发货', pending_recv: '待收货', done: '已完成', cancelled: '已取消', refunding: '退款待审核', refunded: '已退款' }
const reasonLabels: Record<string, string> = { seller_wrong: '发错货（卖方）', seller_quality: '质量问题（卖方）', seller_size: '发错尺码（卖方）', buyer_change: '不想要了/拍错（买方）', buyer_size: '尺码不合适（买方）', buyer_other: '其他（买方）' }
const refundStatus: Record<string, string> = { pending: '待审核', done: '已退款', rejected: '已拒绝', cancelled: '顾客已撤销' }
const yuan = (v: number) => (v / 100).toFixed(2)
const specText = (item: { color: string; size: string; pattern: string }) => [item.color, item.size, item.pattern].filter(Boolean).join(' / ') || '无规格'
async function run(fn: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn() } catch (e) { error.value = e instanceof Error ? e.message : '操作失败' } finally { busy.value = false } }
async function load() { orders.value = (await callAdmin<{ orders: Order[] }>('order.list', { status: status.value })).orders; pendingRefunds.value = (await callAdmin<{ refunds: Refund[] }>('refund.list', { status: 'pending' })).refunds }
async function detail(id: string) { const r = await callAdmin<{ order: Order; refund: typeof refund.value; refunds: Refund[] }>('order.detail', { id }); selected.value = r.order; refund.value = r.refund; orderRefunds.value = r.refunds || []; operation.value = ''; reason.value = ''; company.value = ''; tracking.value = ''; mode.value = 'original' }
function approveRefund(rf: Refund) { run(async () => { await callAdmin('refund.approve', { id: rf._id, data: { route: routeOf(rf._id) } }); await load(); if (selected.value) await detail(selected.value._id); notice.value = '退款已通过并执行' }) }
function rejectRefund() { run(async () => { await callAdmin('refund.reject', { id: refundRejectId.value, data: { reason: refundRejectReason.value } }); refundRejectId.value = ''; refundRejectReason.value = ''; await load(); if (selected.value) await detail(selected.value._id); notice.value = '退款申请已拒绝' }) }
function choose(op: string) { operation.value = op; reason.value = ''; mode.value = 'original' }
function submit() { run(async () => { if (!selected.value) return; await callAdmin('order.' + operation.value, { id: selected.value._id, version: Number(selected.value.version), data: { company: company.value, tracking: tracking.value, reason: reason.value, mode: mode.value } }); await detail(selected.value._id); await load(); notice.value = '订单操作已保存并留痕' }) }
onMounted(() => run(load))
</script>
<template><section class="content order-manager"><div class="section-heading"><div><p class="eyebrow">ORDER OPERATIONS</p><h1>订单管理</h1></div><ElButton @click="run(load)" :loading="busy">刷新订单</ElButton></div><ElAlert v-if="error" :title="error" type="error" :closable="false"/><ElAlert v-if="notice" :title="notice" type="success" :closable="false"/>
<form class="order-filters" @submit.prevent="run(load)"><label>订单状态<select v-model="status" aria-label="订单状态"><option value="">全部状态</option><option v-for="(name,key) in labels" :key="key" :value="key">{{name}}</option></select></label><ElButton native-type="submit" :loading="busy">筛选订单</ElButton></form><p class="muted">按创建时间显示最近100笔；可按状态缩小范围。</p>
<section v-if="pendingRefunds.length" class="refund-queue"><h2>待审核退款（{{pendingRefunds.length}}）</h2><p class="muted">各回各路是余额部分退余额、其余原路退回，全部退余额是整笔都退到顾客余额。</p><article v-for="rf in pendingRefunds" :key="rf._id" class="order-card"><div class="order-summary"><strong>退款 ¥{{yuan(Number(rf.totalAmount))}}</strong><span class="order-tag">{{reasonLabels[rf.reasonCode]||rf.reasonCode}}</span><span>{{new Date(rf.createdAt).toLocaleString('zh-CN')}}</span></div><p class="muted">订单 {{rf.orderId}}</p><p v-for="(l,i) in rf.lines" :key="i">{{l.name}} · {{specText(l)}} × {{l.qty}} · ¥{{yuan(Number(l.amount))}}</p><p>商品 ¥{{yuan(Number(rf.goodsAmount))}}<template v-if="Number(rf.freightAmount)"> · 退运费 ¥{{yuan(Number(rf.freightAmount))}}</template><template v-if="Number(rf.freightComp)"> · 退货运费补偿 ¥{{yuan(Number(rf.freightComp))}}</template> · 原路退回 ¥{{yuan(Number(rf.originalAmount))}}</p><p v-if="rf.reasonText">顾客说明：{{rf.reasonText}}</p><div class="route-row"><label class="checkbox-label"><input type="radio" value="source" :checked="routeOf(rf._id)==='source'" :aria-label="'退款分路各回各路'+rf._id" @change="routePick[rf._id]='source'"/>各回各路</label><label class="checkbox-label"><input type="radio" value="balance" :checked="routeOf(rf._id)==='balance'" :aria-label="'退款分路全部退余额'+rf._id" @change="routePick[rf._id]='balance'"/>全部退余额</label></div><div class="action-row"><ElButton type="primary" @click="approveRefund(rf)">通过并退款</ElButton><ElButton @click="refundRejectId=rf._id;refundRejectReason=''">拒绝</ElButton><ElButton @click="run(()=>detail(rf.orderId))">查看订单</ElButton></div><form v-if="refundRejectId===rf._id" class="admin-form order-operation" @submit.prevent="rejectRefund"><label>拒绝理由<textarea v-model="refundRejectReason" aria-label="退款拒绝理由" required minlength="2" maxlength="500"/></label><ElButton native-type="submit" type="primary" :loading="busy">确认拒绝</ElButton></form></article></section>
<article v-for="o in orders" :key="o._id" class="order-card" :data-order-id="o._id"><div class="order-summary"><strong>{{labels[o.status]}}</strong><span v-if="Number(o.refundedAmount||0)>0" class="order-tag">部分退款</span><span>¥{{yuan(Number(o.payAmount))}}</span></div><p class="muted">{{o._id}}<br>{{new Date(o.createdAt).toLocaleString('zh-CN')}}</p><p v-for="(item,i) in o.items" :key="i">{{item.name}} · {{specText(item)}} × {{item.qty}}</p><ElButton @click="run(()=>detail(o._id))">查看及处理</ElButton></article>
<ElDialog :model-value="!!selected" @close="selected=undefined" title="订单详情与处理" width="min(720px, calc(100vw - 24px))"><template v-if="selected"><ElAlert v-if="error" :title="error" type="error" :closable="false"/><p class="order-id">{{selected._id}}</p><h3>{{labels[selected.status]}} · ¥{{yuan(Number(selected.payAmount))}}</h3><p>付款构成：<template v-if="Number(selected.balancePaid)>0">余额 ¥{{yuan(Number(selected.balancePaid))}} / 微信模拟 ¥{{yuan(Number(selected.wxPaid))}}（历史订单）</template><template v-else>模拟支付 ¥{{yuan(Number(selected.wxPaid))}}</template></p><p>{{selected.address.name}} · {{selected.address.phone}}<br>{{selected.address.region}} {{selected.address.detail}}</p><p>会员编号：{{selected.memberNo||'—'}}</p><p v-if="selected.expressNo">{{selected.expressCompany}}：{{selected.expressNo}}</p><p v-if="selected.refundReason">退款理由：{{selected.refundReason}}</p><ElAlert v-if="refund" :title="'本单已退款 ¥'+yuan(Number(refund.balanceAmount)+Number(refund.originalAmount))+'（余额 ¥'+yuan(Number(refund.balanceAmount))+' · 原路 ¥'+yuan(Number(refund.originalAmount))+'）'+(refund.originalStatus==='pending_simulated'?'（模拟，未实际退款）':'')" type="info" :closable="false"/>
<div v-if="orderRefunds.length" class="order-refunds"><h3>退款记录</h3><p class="muted">各回各路是余额部分退余额、其余原路退回，全部退余额是整笔都退到顾客余额。</p><div v-for="rf in orderRefunds" :key="rf._id" class="refund-row"><p><strong>{{refundStatus[rf.status]||rf.status}} · ¥{{yuan(Number(rf.totalAmount))}}</strong> · {{reasonLabels[rf.reasonCode]||rf.reasonCode}} · {{new Date(rf.createdAt).toLocaleString('zh-CN')}}</p><p v-for="(l,i) in rf.lines" :key="i" class="muted">{{l.name}} · {{specText(l)}} × {{l.qty}} · ¥{{yuan(Number(l.amount))}}</p><p class="muted">商品 ¥{{yuan(Number(rf.goodsAmount))}}<template v-if="Number(rf.freightAmount)"> · 退运费 ¥{{yuan(Number(rf.freightAmount))}}</template><template v-if="Number(rf.freightComp)"> · 退货运费补偿 ¥{{yuan(Number(rf.freightComp))}}</template> · 原路退回 ¥{{yuan(Number(rf.originalAmount))}}<template v-if="rf.rejectReason"> · 拒绝理由：{{rf.rejectReason}}</template></p><div v-if="rf.status==='pending'" class="route-row"><label class="checkbox-label"><input type="radio" value="source" :checked="routeOf(rf._id)==='source'" :aria-label="'退款分路各回各路'+rf._id" @change="routePick[rf._id]='source'"/>各回各路</label><label class="checkbox-label"><input type="radio" value="balance" :checked="routeOf(rf._id)==='balance'" :aria-label="'退款分路全部退余额'+rf._id" @change="routePick[rf._id]='balance'"/>全部退余额</label></div><div v-if="rf.status==='pending'" class="action-row"><ElButton type="primary" @click="approveRefund(rf)">通过并退款</ElButton><ElButton @click="refundRejectId=rf._id;refundRejectReason=''">拒绝</ElButton></div><form v-if="refundRejectId===rf._id" class="admin-form order-operation" @submit.prevent="rejectRefund"><label>拒绝理由<textarea v-model="refundRejectReason" aria-label="退款拒绝理由" required minlength="2" maxlength="500"/></label><ElButton native-type="submit" type="primary" :loading="busy">确认拒绝</ElButton></form></div></div>
<div class="action-row"><template v-if="selected.status==='pending_ship'"><ElButton @click="choose('ship')">填写发货</ElButton></template><template v-if="selected.status==='refunding'"><ElButton @click="choose('refund.approve')">审核退款</ElButton><ElButton @click="choose('refund.reject')">驳回退款申请</ElButton></template></div>
<form v-if="operation" class="admin-form order-operation" @submit.prevent="submit"><template v-if="operation==='ship'"><label>快递公司<input v-model="company" aria-label="快递公司" required maxlength="60"/></label><label>快递单号<input v-model="tracking" aria-label="快递单号" required maxlength="80"/></label></template><label v-if="operation.endsWith('reject')">驳回理由<textarea v-model="reason" aria-label="审核理由" required minlength="2" maxlength="500"/></label><template v-if="operation==='refund.approve'"><p class="muted">原路退回是按顾客付款方式各回各路，全部退余额是整笔都退到顾客余额；金额由服务器按订单实付计算，微信部分仅生成待退模拟记录。退款不自动回库。</p><div class="route-row"><label class="checkbox-label"><input v-model="mode" type="radio" value="original" aria-label="整单退款原路退回"/>原路退回</label><label class="checkbox-label"><input v-model="mode" type="radio" value="balance" aria-label="整单退款全部退余额"/>全部退余额</label></div></template><ElButton native-type="submit" type="primary" :loading="busy">确认订单操作</ElButton></form></template></ElDialog></section></template>
<style>
.refund-queue{margin:20px 0}.refund-queue h2{font-size:18px}.order-refunds{border-top:1px solid #e4e9f1;margin-top:16px;padding-top:8px}.refund-row{border-bottom:1px solid #edf1f6;padding:10px 0}.order-filters{display:flex;flex-wrap:wrap;gap:16px;align-items:flex-end}.order-filters label{display:grid;gap:8px;font-size:13px}.order-filters select{font:inherit;padding:10px;border:1px solid #dce2ec;border-radius:6px}.order-card{background:white;padding:20px;border:1px solid #e4e9f1;border-radius:8px;margin:16px 0;overflow-wrap:anywhere}.order-summary{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.order-summary>span:last-child{margin-left:auto}.order-tag{background:#eef3ff;color:#0038d1;border-radius:4px;font-size:12px;padding:4px 8px}.order-id{overflow-wrap:anywhere;color:#677185;font-size:12px}.order-operation{border-top:1px solid #e4e9f1;margin-top:20px;padding-top:20px}.route-row{display:flex;gap:16px;flex-wrap:wrap;margin:10px 0;align-items:center}.route-row .checkbox-label{display:flex;gap:6px;align-items:center;font-size:13px;cursor:pointer}.route-row input{width:auto;margin:0}@media(max-width:768px){.order-card{padding:16px}.order-manager .section-heading{align-items:flex-start;gap:12px}.order-manager .section-heading h1{font-size:26px}.order-filters{gap:12px}.order-filters label{flex:1;min-width:120px}.order-filters select{width:100%}.order-manager .el-dialog p{overflow-wrap:anywhere}}
</style>
